{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 4,
      "reason": "文章回答題目並表明立場（\"I believe all restaurants should follow this rule.\"）並提供兩點理由及反駁，符合任務要求與語域。"
    },
    {
      "id": "organization",
      "score": 4,
      "reason": "分段清楚，有引言、兩個主要段落與結論，使用連接詞如 \"First\", \"Second\", \"However\"，結構合理。"
    },
    {
      "id": "vocabulary",
      "score": 3,
      "reason": "用詞大多恰當（如 \"environment\", \"protect nature\"），但有拼寫錯誤（\"enviroment\", \"recieve\", \"definately\"）與少數用詞不精準。"
    },
    {
      "id": "grammar",
      "score": 3,
      "reason": "句子大多正確且易懂，但有幾處文法或拼寫問題（例如時態、拼字與複數/不可數名詞使用需小修）。"
    }
  ],
  "issues": [
    {
      "quote": "enviroment",
      "type": "spelling",
      "why": "此單字拼寫錯誤，應為 \"environment\"，拼錯會影響正式寫作的品質。",
      "suggestion": "environment"
    },
    {
      "quote": "recieve",
      "type": "spelling",
      "why": "此單字拼寫錯誤（常見的 'i before e' 規則例外要注意），正確拼法為 \"receive\"。",
      "suggestion": "receive"
    },
    {
      "quote": "I definately support stopping free plastic straws and utensils.",
      "type": "spelling",
      "why": "單字 'definately' 拼錯，並且句尾可修為更自然的表達。",
      "suggestion": "I definitely support stopping free plastic straws and utensils."
    }
  ],
  "more": [
    {
      "quote": "plastic is very bad for the enviroment.",
      "type": "article",
      "why": "在正式寫作中，'plastic' 作為一般材料時通常用不可數或加定冠詞來更清楚；句首也應大寫。",
      "suggestion": "Plastic is very bad for the environment."
    },
    {
      "quote": "Most plastic straws and forks are used for only a few minutes, but they stay in the ocean for hundreds of years.",
      "type": "cohesion",
      "why": "句子內容清楚，但可用更精確的連接詞或數據支持論點以增強說服力。",
      "suggestion": "Most plastic straws and forks are used for only a few minutes, yet they can remain in the ocean for hundreds of years."
    },
    {
      "quote": "When they order a drink, they sometimes recieve a small discount for bringing their own cup, so it also saves money.",
      "type": "grammar",
      "why": "句子結構冗長，且最後的 'so it also saves money' 主詞不明，應明確指出主語。",
      "suggestion": "When they order a drink, they sometimes receive a small discount for bringing their own cup, so they also save money."
    },
    {
      "quote": "Some people say that this rule is inconvenient.",
      "type": "tone",
      "why": "句子可以更具體，例如說明誰覺得不便或為什麼，會使論證更完整。",
      "suggestion": "Some people argue that the rule is inconvenient because they forget to bring reusable items."
    },
    {
      "quote": "Sea turtles and fish often eat them by mistake.",
      "type": "word-choice",
      "why": "'Eat them' 可以更準確地表達為 'mistake them for food' 以呈現原因與後果。",
      "suggestion": "Sea turtles and fish often mistake them for food and eat them."
    }
  ],
  "strengths": [
    {
      "quote": "I believe all restaurants should follow this rule.",
      "why": "清楚表達立場，讓讀者一開始即了解作者的觀點。"
    },
    {
      "quote": "Many of my friends now carry their own metal straws and chopsticks.",
      "why": "使用具體例子支撐論點，使論證更有說服力。"
    }
  ],
  "summary": "整體寫作有清楚立場、合理段落與具體例子，接下來應注意拼字（如 environment, receive, definitely）和細節語法（主詞一致與句子銜接）。加強句子精準表達與少量連接詞使用，能讓文章更流暢有力。"
}
